require_once __DIR__.'/backend/conexion.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT p.*,d.sku,d.marca,d.precio_anterior,d.garantia,d.especificaciones,d.galeria,d.destacado FROM productos p LEFT JOIN producto_detalles d ON d.producto_id=p.id WHERE p.id=? AND p.activo=1");$q->execute([$id]);$product=$q->fetch();if(!$product){http_response_code(404);exit('Producto no encontrado.');}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function image_url($v){$v=trim((string)$v);if($v==='')return 'https://placehold.co/800x800?text=Producto';if(str_starts_with($v,'//'))return 'https:'.$v;if(preg_match('~^https?://~i',$v))return $v;if(preg_match('~^(?:javascript|data|vbscript):~i',$v))return 'https://placehold.co/800x800?text=Producto';return $v;}$spec=json_decode($product['especificaciones']??'[]',true)?:[];$gallery=json_decode($product['galeria']??'[]',true)?:[];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($product['nombre'])?> | Xiaomi Store Arequipa</title><link rel="stylesheet" href="styles.css"><style>.detail{max-width:1100px;margin:40px auto;padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:35px;background:#fff;border-radius:18px}.detail img{width:100%;max-height:480px;object-fit:contain}.detail h1{font-size:32px}.price{font-size:28px;color:#d32f2f;font-weight:800}.old{text-decoration:line-through;color:#888}.specs{padding-left:20px}.detail button{padding:13px 20px;border:0;border-radius:8px;background:#e53935;color:white;cursor:pointer}@media(max-width:700px){.detail{grid-template-columns:1fr;margin:15px}}</style></head><body><header style="padding:18px 5%;background:#171717;color:#fff"><a href="index.php" style="color:white;text-decoration:none">← Xiaomi Store Arequipa</a>　<a href="perfil.php" style="color:white">Mi cuenta</a></header><main class="detail"><div><img src="<?=h(image_url($product['imagen']))?>" alt="<?=h($product['nombre'])?>" onerror="this.onerror=null;this.src='https://placehold.co/800x800?text=Producto'"><?php foreach($gallery as $img):?><img style="width:75px;height:75px" src="<?=h(image_url($img))?>" alt="Imagen adicional" onerror="this.onerror=null;this.src='https://placehold.co/200x200?text=Imagen'"><?php endforeach?></div><section><small><?=h($product['categoria'])?> · <?=h($product['marca']??'Xiaomi')?></small><h1><?=h($product['nombre'])?></h1><p><?=h($product['descripcion'])?></p><p class="price">S/ <?=number_format($product['precio'],2)?></p><?php if($product['precio_anterior']):?><p class="old">S/ <?=number_format($product['precio_anterior'],2)?></p><?php endif?><p><?=((int)$product['stock']>0?'Disponible: '.$product['stock'].' unidades':'Agotado')?></p><p><b>Garantía:</b> <?=h($product['garantia']??'Consultar condiciones')?></p><h3>Especificaciones</h3><ul class="specs"><?php foreach($spec as $k=>$v):?><li><b><?=h($k)?>:</b> <?=h($v)?></li><?php endforeach?></ul><button type="button" id="addDetailCart">Agregar al carrito</button><p><a href="catalogo.php">Seguir comprando</a></p><script type="module">import { globalCart } from "./js/models/cart.model.js"; document.getElementById("addDetailCart").addEventListener("click",()=>{globalCart.addItem({id:<?= (int)$product['id']?>,name:<?= json_encode($product['nombre'],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>,price:<?= (float)$product['precio']?>,image:<?= json_encode($product['imagen']??'',JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>});alert("Producto agregado al carrito. Continúa en la tienda para finalizar la compra.");location.href="index.php";});</script></section></main></body></html>
